using System.Text.Json;
namespace BeastCloud;

public sealed partial class Cloud
{
    static void MapSharing(WebApplication app)
    {
        app.MapGet("/api/users", (Database d) => d.Rows("SELECT id,name,role FROM users"));
        app.MapPost("/api/users", (HttpContext c, Cloud x, JsonElement j) => { var id = Id(); x.db.Execute("INSERT INTO users(id,name,password,role) VALUES($id,$n,$p,'restricted')", ("$id", id), ("$n", Storage.Name(S(j, "name") ?? "")), ("$p", x.security.Password(S(j, "password") ?? ""))); x.db.Audit(Actor(c), "account.created", id); return new { id }; });
        app.MapDelete("/api/users/{id}", (HttpContext c, Database d, string id) => { if (id == Actor(c)) throw new ArgumentException("Cannot delete owner"); d.Transaction(db => { Database.Exec(db, "DELETE FROM sessions WHERE userId=$id", ("$id", id)); Database.Exec(db, "DELETE FROM shares WHERE userId=$id", ("$id", id)); Database.Exec(db, "DELETE FROM users WHERE id=$id AND role='restricted'", ("$id", id)); }); return Results.Ok(); });
        app.MapGet("/api/shares", (Database d) => d.Rows("SELECT s.id,s.itemId,s.userId,s.expires,s.write,s.created,i.name FROM shares s JOIN items i ON i.id=s.itemId"));
        app.MapPost("/api/shares", (HttpContext c, Cloud x, JsonElement j) => { var item = S(j, "itemId") ?? ""; if ((string)x.Item(item)["kind"] != "file") throw new ArgumentException("Sharing currently supports individual files"); var expires = S(j, "expires"); if (expires != null && (!DateTimeOffset.TryParse(expires, out var exp) || exp <= DateTimeOffset.UtcNow)) throw new ArgumentException("Expiration must be in the future"); var user = S(j, "userId"); if (user != null && x.db.Scalar("SELECT id FROM users WHERE id=$id", ("$id", user)) == null) throw new ArgumentException("Account not found"); if (user == null && B(j, "write")) throw new ArgumentException("Bearer links are read-only"); var id = Id(); var token = user == null ? Storage.Token() : null; var pw = S(j, "password"); x.db.Execute("INSERT INTO shares VALUES($id,$i,$u,$t,$p,$e,$w,$c)", ("$id", id), ("$i", item), ("$u", user), ("$t", token == null ? null : Storage.Hash(token)), ("$p", string.IsNullOrEmpty(pw) ? null : x.security.Password(pw)), ("$e", expires == null ? null : DateTimeOffset.Parse(expires).ToUniversalTime().ToString("O")), ("$w", B(j, "write")), ("$c", Database.Now)); x.db.Audit(Actor(c), "share.created", id); return new { id, token }; });
        app.MapDelete("/api/shares/{id}", (HttpContext c, Database d, string id) => { d.Execute("DELETE FROM shares WHERE id=$id", ("$id", id)); d.Audit(Actor(c), "share.revoked", id); return Results.Ok(); });
        app.MapGet("/api/shared", (HttpContext c, Database d) => d.Rows("SELECT s.id,s.itemId,s.write,s.expires,i.name,i.size FROM shares s JOIN items i ON i.id=s.itemId WHERE s.userId=$u AND (s.expires IS NULL OR s.expires>$n) AND i.deleted IS NULL", ("$u", Actor(c)), ("$n", Database.Now)));
        app.MapGet("/api/shared/{id}/content", (HttpContext c, Cloud x, string id) => { var s = x.Grant(id, Actor(c)); x.db.Audit(Actor(c), "share.download", id); return x.Content(x.Item((string)s["itemId"]!), false); });
        app.MapPut("/api/shared/{id}/content", async (HttpContext c, Cloud x, string id) => { var s = x.Grant(id, Actor(c)); if (Convert.ToInt64(s["write"]) != 1) return Results.StatusCode(403); var i = x.Item((string)s["itemId"]!); var len = c.Request.ContentLength ?? 0; if (len <= 0 || len > 4 * 1024 * 1024) throw new ArgumentException("Shared write supports a single file up to 4 MiB"); using var j = JsonDocument.Parse(JsonSerializer.Serialize(new { name = i["name"], parent = i["parent"], itemId = i["id"], total = len, baseRevision = i["revision"] })); var transfer = JsonSerializer.SerializeToElement(await x.BeginUpload(Actor(c), j.RootElement)); var upload = S(transfer, "id")!; c.Request.Headers["Upload-Offset"] = "0"; await x.Chunk(upload, Actor(c), c); return Results.Ok(new { id = await x.Commit(upload, Actor(c)) }); });
        // The secret is sent in a POST body, never in URLs or server access logs.
        app.MapPost("/api/public/download", (HttpContext c, Cloud x, JsonElement j) => { var token = S(j, "token") ?? ""; var s = x.db.Rows("SELECT * FROM shares WHERE token=$t AND (expires IS NULL OR expires>$n)", ("$t", Storage.Hash(token)), ("$n", Database.Now)).FirstOrDefault(); if (s == null || s["password"] is string pw && !x.security.Verify(pw, S(j, "password") ?? "")) return Results.NotFound(); x.db.Audit("bearer", "share.download", (string)s["id"]!); return x.Content(x.Item((string)s["itemId"]!), false); }).RequireRateLimiting("auth");
    }
    Dictionary<string, object?> Grant(string id, string user) => db.Rows("SELECT * FROM shares WHERE id=$id AND userId=$u AND (expires IS NULL OR expires>$n)", ("$id", id), ("$u", user), ("$n", Database.Now)).FirstOrDefault() ?? throw new ArgumentException("Share unavailable");
    static void MapSync(WebApplication app)
    {
        app.MapGet("/api/devices", (Database d) => d.Rows("SELECT id,name,folder,mode,lastSeen,paused FROM devices"));
        app.MapPost("/api/devices", (HttpContext c, Cloud x, JsonElement j) => { var folder = S(j, "folder"); x.Parent(folder); if (folder == null) throw new ArgumentException("Select a dedicated sync folder"); var mode = S(j, "mode") ?? "two-way"; if (mode is not ("upload-only" or "download-only" or "two-way")) throw new ArgumentException("Invalid sync mode"); var id = Id(); var code = Storage.Token(); x.db.Execute("INSERT INTO devices(id,name,folder,mode,pair,expires) VALUES($id,$n,$f,$m,$p,$e)", ("$id", id), ("$n", S(j, "name") ?? "Windows device"), ("$f", folder), ("$m", mode), ("$p", Storage.Hash(code)), ("$e", DateTimeOffset.UtcNow.AddMinutes(10).ToString("O"))); x.db.Audit(Actor(c), "device.invited", id); return new { id, code }; });
        app.MapPatch("/api/devices/{id}", (Database d, string id, JsonElement j) => { d.Execute("UPDATE devices SET paused=$p WHERE id=$id", ("$p", B(j, "paused")), ("$id", id)); return Results.Ok(); });
        app.MapDelete("/api/devices/{id}", (HttpContext c, Database d, string id) => { d.Execute("DELETE FROM devices WHERE id=$id", ("$id", id)); d.Audit(Actor(c), "device.revoked", id); return Results.Ok(); });
        app.MapPost("/api/pair", async (Cloud x, JsonElement j) => { object? result = null; await Locked(x.disk, () => { var d = x.db.Rows("SELECT * FROM devices WHERE pair=$p AND expires>$n", ("$p", Storage.Hash(S(j, "code") ?? "")), ("$n", Database.Now)).FirstOrDefault() ?? throw new ArgumentException("Pairing code invalid or expired"); var token = Storage.Token(); x.db.Execute("UPDATE devices SET token=$t,pair=NULL,expires=NULL WHERE id=$id", ("$t", Storage.Hash(token)), ("$id", d["id"])); result = new { id = d["id"], token, folder = d["folder"], mode = d["mode"] }; return Task.CompletedTask; }); return Results.Ok(result); }).RequireRateLimiting("auth");
        app.MapGet("/api/sync/manifest", (HttpContext c, Cloud x) => { x.disk.Available(); var d = (Dictionary<string, object?>)c.Items["device"]!; var folder = (string)d["folder"]!; if (x.Item(folder, true)["deleted"] != null) throw new IOException("Sync root is in trash; reconciliation suspended"); return new { mode = d["mode"], items = x.db.Rows("WITH RECURSIVE tree(id) AS (SELECT $f UNION ALL SELECT i.id FROM items i JOIN tree t ON i.parent=t.id) SELECT * FROM items WHERE id IN tree AND id<>$f", ("$f", folder)) }; });
        app.MapGet("/api/sync/content/{id}", (HttpContext c, Cloud x, string id) => { var d = (Dictionary<string, object?>)c.Items["device"]!; if ((string)d["mode"] != "upload-only" && x.Within(id, (string)d["folder"]!)) return x.Content(x.Item(id), false); return Results.StatusCode(403); });
        app.MapPost("/api/sync/folders", async (HttpContext c, Cloud x, JsonElement j) => { var d = (Dictionary<string, object?>)c.Items["device"]!; if ((string)d["mode"] == "download-only" || !x.Within(S(j, "parent") ?? "", (string)d["folder"]!)) return Results.StatusCode(403); var id = Id(); await Locked(x.disk, () => { x.Parent(S(j, "parent")); x.db.Execute("INSERT INTO items(id,parent,name,kind,modified) VALUES($id,$p,$n,'folder',$t)", ("$id", id), ("$p", S(j, "parent")), ("$n", Storage.Name(S(j, "name") ?? "")), ("$t", Database.Now)); return Task.CompletedTask; }); return Results.Ok(new { id }); });
        app.MapPost("/api/sync/uploads", async (HttpContext c, Cloud x, JsonElement j) => { var d = (Dictionary<string, object?>)c.Items["device"]!; if ((string)d["mode"] == "download-only" || !x.Within(S(j, "parent") ?? "", (string)d["folder"]!)) return Results.StatusCode(403); if (S(j, "itemId") is string item && !x.Within(item, (string)d["folder"]!)) return Results.StatusCode(403); return Results.Ok(await x.BeginUpload((string)d["id"]!, j)); });
        app.MapGet("/api/sync/uploads/{id}", (HttpContext c, Cloud x, string id) => x.Upload(id, (string)((Dictionary<string, object?>)c.Items["device"]!)["id"]!));
        app.MapPatch("/api/sync/uploads/{id}", async (HttpContext c, Cloud x, string id) => Results.Ok(new { offset = await x.Chunk(id, (string)((Dictionary<string, object?>)c.Items["device"]!)["id"]!, c) }));
        app.MapPost("/api/sync/uploads/{id}/commit", async (HttpContext c, Cloud x, string id) => { var d = (Dictionary<string, object?>)c.Items["device"]!; var u = x.Upload(id, (string)d["id"]!); if ((string)d["mode"] == "download-only" || !x.Within((string)u["parent"]!, (string)d["folder"]!)) return Results.StatusCode(403); return Results.Ok(new { id = await x.Commit(id, (string)d["id"]!) }); });
        app.MapDelete("/api/sync/items/{id}", async (HttpContext c, Cloud x, string id) => { var d = (Dictionary<string, object?>)c.Items["device"]!; if ((string)d["mode"] == "download-only" || id == (string)d["folder"]! || !x.Within(id, (string)d["folder"]!)) return Results.StatusCode(403); await Locked(x.disk, () => { if ((string)x.Item(id)["kind"] != "file") throw new ArgumentException("Sync only propagates file deletions"); x.db.Execute("UPDATE items SET deleted=$n,modified=$n WHERE id=$id", ("$n", Database.Now), ("$id", id)); x.db.Audit((string)d["id"]!, "sync.trashed", id); return Task.CompletedTask; }); return Results.Ok(); });
    }
}
